import { useEffect, useMemo, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { Sparkles, X, ArrowRight } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { Badge } from '@/components/ui/Badge';
import { SearchBar } from '@/components/explorer/SearchBar';
import { PromptPreview } from '@/components/preview/PromptPreview';
import {
  loadCompatibility,
  loadEnglishExamples,
  loadProtocols,
  loadStrategies,
  loadTermMetadata,
} from '@/lib/utils/dataLoader';
import { useWizardStore } from '@/lib/store/wizardStore';
import { usePromptStore } from '@/lib/store/promptStore';
import { useLanguage } from '@/components/layout/LanguageProvider';
import { buildPrompt } from '@/lib/engine';
import { siteConfig } from '@/config/site.config';
import type { EnrichedTerm } from '@/types/knowledge.types';
import type { ComposedPrompt } from '@/types/prompt.types';

export default function CustomPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const { t ,lang } = useLanguage();
  const { answers, setAnswers } = useWizardStore();
  const { current: currentPrompt, setCurrent } = usePromptStore();

  const [terms, setTerms] = useState<EnrichedTerm[]>([]);
  const [q, setQ] = useState('');
  const [selected, setSelected] = useState<number[]>(answers.customTermIds || []);
  const [customTopic, setCustomTopic] = useState(answers.topic || '');
  const [generating, setGenerating] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Load terms
  useEffect(() => {
    loadTermMetadata()
      .then((m) => setTerms(m.terms as EnrichedTerm[]))
      .catch((e: unknown) => {
        setError(e instanceof Error ? e.message : t('errors.loadFailed'));
      });
  }, [t]);

  // Receive prompt from History (view custom)
  useEffect(() => {
    const state = location.state as { promptToView?: ComposedPrompt } | null;
    if (state?.promptToView) {
      setCurrent(state.promptToView);
    }
  }, [location.key, setCurrent]);

  const filtered = useMemo(
    () =>
      terms.filter(
        (x) =>
          !q ||
          x.term_ar.includes(q) ||
          x.term_en.toLowerCase().includes(q.toLowerCase()),
      ),
    [terms, q],
  );

  const selectedTerms = terms.filter((x) => selected.includes(x.id));

  function toggle(id: number) {
    setSelected((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]));
  }

  async function handleGenerate() {
    if (selected.length === 0) return;
    setGenerating(true);
    setError(null);
    try {
      const [metadata, protocols, strategies, compatibility] = await Promise.all([
        loadTermMetadata(),
        loadProtocols(),
        loadStrategies(),
        loadCompatibility(),
        loadEnglishExamples(),
      ]);

      const finalAnswers = {
        ...answers,
        mode: 'custom' as const,
        customTermIds: selected,
        topic: customTopic.trim() || undefined,
      };

      setAnswers({
        mode: 'custom',
        customTermIds: selected,
        topic: customTopic.trim() || undefined,
      });

      const result = buildPrompt({
        answers: finalAnswers,
        termMetadata: metadata,
        protocols,
        strategies,
        compatibility,
      });

      setCurrent(result);
      // ❌ No navigation — show inline preview
    } catch (e) {
      setError(e instanceof Error ? e.message : t('errors.generationFailed'));
    } finally {
      setGenerating(false);
    }
  }

  // Show preview inline
  if (currentPrompt) {
    return (
      <div className="mx-auto max-w-4xl px-4 py-10 sm:px-6">
        <div className="mb-4">
          <Button
            variant="ghost"
            onClick={() => {
              setCurrent(null);
              setSelected([]);
              setCustomTopic('');
            }}
          >
            <ArrowRight size={16} /> {t('wizard.newPrompt')}
          </Button>
        </div>
        <PromptPreview prompt={currentPrompt} />
      </div>
    );
  }

  return (
    <div className="mx-auto max-w-6xl px-4 py-10 sm:px-6">
      <div className="mb-6">
        <h1 className="mb-1 text-3xl font-bold text-gradient">{t('custom.title')}</h1>
        <p className="text-sm text-text-secondary">{t('custom.subtitle')}</p>
      </div>

      <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
        <div>
          <SearchBar value={q} onChange={setQ} placeholder={t('custom.searchPlaceholder')} />
          <div className="mt-4 max-h-[600px] space-y-2 overflow-y-auto pe-1">
            {filtered.map((term) => {
              const isSelected = selected.includes(term.id);
              const color =
                (siteConfig.theme.colors.categories as Record<string, string>)[term.category] ||
                siteConfig.theme.colors.primary;
              return (
                <button
                  key={term.id}
                  onClick={() => toggle(term.id)}
                  className={`w-full rounded-lg border p-3 text-start transition-all ${
                    isSelected
                      ? 'border-primary bg-primary/10'
                      : 'border-border bg-surface hover:border-primary/50'
                  }`}
                >
                  <div className="mb-1 flex items-center justify-between">
                    <Badge color={color}>{term.category}</Badge>
                    {isSelected && (
                      <span className="text-xs font-bold text-primary">✓</span>
                    )}
                  </div>
                  <p className="text-sm font-bold text-text-primary">
                    {lang === 'ar' ? term.term_ar : term.term_en}
                  </p>
                  <p
                    className="text-xs text-text-muted"
                    dir={lang === 'ar' ? 'ltr' : 'rtl'}
                  >
                    {lang === 'ar' ? term.term_en : term.term_ar}
                  </p>
                </button>
              );
            })}
          </div>
        </div>

        <div className="lg:sticky lg:top-20 lg:self-start">
          <Card padding="md">
            <div className="mb-3 flex items-center justify-between">
              <h3 className="text-sm font-bold text-text-primary">
                {t('custom.selected', { count: selected.length })}
              </h3>
              {selected.length > 0 && (
                <button
                  onClick={() => setSelected([])}
                  className="text-xs text-text-muted hover:text-error"
                >
                  {t('common.clearAll')}
                </button>
              )}
            </div>

            {selectedTerms.length === 0 ? (
              <p className="rounded-lg border border-dashed border-border p-4 text-center text-xs text-text-muted">
                {t('custom.noSelection')}
              </p>
            ) : (
              <div className="max-h-[300px] space-y-1 overflow-y-auto">
                {selectedTerms.map((term) => (
                  <div
                    key={term.id}
                    className="flex items-center justify-between rounded-md bg-surface-elevated px-2 py-1.5 text-xs"
                  >
                    <span className="flex-1 truncate text-text-primary">
                      <p className="text-sm font-bold text-text-primary">
                        {lang === 'ar' ? term.term_ar : term.term_en}
                      </p>
                    </span>
                    <button
                      onClick={() => toggle(term.id)}
                      className="text-text-muted hover:text-error"
                    >
                      <X size={14} />
                    </button>
                  </div>
                ))}
              </div>
            )}

            <div className="mt-4">
              <label className="mb-2 block text-sm font-bold text-text-primary">
                {t('custom.ideaLabel')}
              </label>
              <p className="mb-2 text-xs text-text-muted">{t('custom.ideaHint')}</p>
              <textarea
                value={customTopic}
                onChange={(e) => setCustomTopic(e.target.value)}
                rows={3}
                placeholder={t('custom.ideaPlaceholder')}
                className="w-full resize-none rounded-xl border border-border bg-surface p-3 text-sm text-text-primary placeholder:text-text-muted focus:border-primary focus:outline-none focus:ring-2 focus:ring-primary/20"
              />
            </div>

            {error && (
              <p
                role="alert"
                className="mt-3 rounded-lg border border-error/40 bg-error/10 p-3 text-sm text-error"
              >
                {error}
              </p>
            )}

            <Button
              fullWidth
              className="mt-4"
              onClick={handleGenerate}
              loading={generating}
              disabled={selected.length === 0}
            >
              <Sparkles size={16} /> {t('custom.generate')}
            </Button>
          </Card>
        </div>
      </div>
    </div>
  );
}